<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{AccountingAccount,Expense,JournalEntry,Sale,SaleItem,SaleReturn,StockAdjustment}; use App\Services\BranchContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class AccountingController extends Controller
{
 public function accounts(){return AccountingAccount::where('is_active',true)->orderBy('code')->get();}
 public function journals(){return JournalEntry::with('lines.account')->where('branch_id',BranchContext::id())->latest('entry_date')->paginate(25);}
 public function storeJournal(Request $r){$d=$r->validate(['entry_date'=>'required|date','narration'=>'required|string|max:255','lines'=>'required|array|min:2','lines.*.account_id'=>'required|exists:accounting_accounts,id','lines.*.debit'=>'nullable|numeric|min:0','lines.*.credit'=>'nullable|numeric|min:0','lines.*.description'=>'nullable|string|max:255']);$debit=round(collect($d['lines'])->sum('debit'),2);$credit=round(collect($d['lines'])->sum('credit'),2);if($debit<=0||abs($debit-$credit)>0.01)throw ValidationException::withMessages(['lines'=>'Journal entry must have equal debit and credit totals greater than zero.']);$j=DB::transaction(function()use($d,$debit){$j=JournalEntry::create(['entry_no'=>'JV-'.now()->format('Ymd').'-'.strtoupper(str()->random(5)),'branch_id'=>BranchContext::id(),'entry_date'=>$d['entry_date'],'narration'=>$d['narration'],'status'=>'posted','created_by'=>auth()->id(),'posted_at'=>now()]);foreach($d['lines'] as $line)$j->lines()->create(['account_id'=>$line['account_id'],'debit'=>$line['debit']??0,'credit'=>$line['credit']??0,'description'=>$line['description']??null]);return $j;});return response()->json(['message'=>'Balanced journal posted.','data'=>$j->load('lines.account')],201);}
 public function incomeStatement(Request $r){$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$d['from']??today()->startOfMonth()->toDateString();$to=$d['to']??today()->toDateString();$sales=(float)Sale::leftJoin('tax_profiles as tp','tp.id','=','sales.tax_profile_id')->where('sales.branch_id',BranchContext::id())->whereBetween('sales.sale_date',[$from,$to])->sum(DB::raw("sales.subtotal-sales.discount-CASE WHEN tp.calculation='inclusive' THEN sales.tax ELSE 0 END"));$returns=(float)SaleReturn::leftJoin('sales as rs','rs.id','=','sale_returns.sale_id')->leftJoin('tax_profiles as rtp','rtp.id','=','rs.tax_profile_id')->where('sale_returns.branch_id',BranchContext::id())->whereBetween('sale_returns.return_date',[$from,$to])->sum(DB::raw("sale_returns.total-CASE WHEN rtp.calculation='inclusive' AND rs.subtotal>0 THEN (rs.tax*sale_returns.total/rs.subtotal) ELSE 0 END"));$restocked=DB::table('sale_return_items')->where('restocked',true)->whereNotNull('sale_item_id')->groupBy('sale_item_id')->selectRaw('sale_item_id,SUM(quantity) as restocked_qty');$cogs=(float)SaleItem::join('sales','sales.id','=','sale_items.sale_id')->leftJoinSub($restocked,'ri',fn($j)=>$j->on('ri.sale_item_id','=','sale_items.id'))->where('sales.branch_id',BranchContext::id())->whereBetween('sales.sale_date',[$from,$to])->sum(DB::raw('sale_items.cost_price * CASE WHEN sale_items.quantity - COALESCE(ri.restocked_qty,0) > 0 THEN sale_items.quantity - COALESCE(ri.restocked_qty,0) ELSE 0 END'));$expenses=(float)Expense::where('status','approved')->where('branch_id',BranchContext::id())->whereBetween('expense_date',[$from,$to])->sum('amount');$writeoffs=(float)StockAdjustment::join('medicine_batches','medicine_batches.id','=','stock_adjustments.medicine_batch_id')->where('stock_adjustments.branch_id',BranchContext::id())->where('stock_adjustments.type','subtract')->whereBetween('stock_adjustments.created_at',[$from.' 00:00:00',$to.' 23:59:59'])->sum(DB::raw('stock_adjustments.quantity * medicine_batches.purchase_price'));$adjustmentGains=(float)StockAdjustment::join('medicine_batches','medicine_batches.id','=','stock_adjustments.medicine_batch_id')->where('stock_adjustments.branch_id',BranchContext::id())->where('stock_adjustments.type','add')->whereBetween('stock_adjustments.created_at',[$from.' 00:00:00',$to.' 23:59:59'])->sum(DB::raw('stock_adjustments.quantity * medicine_batches.purchase_price'));$netSales=round($sales-$returns,2);$gross=round($netSales-$cogs,2);return response()->json(['from'=>$from,'to'=>$to,'gross_sales'=>$sales,'sales_returns'=>$returns,'net_sales'=>$netSales,'cost_of_goods_sold'=>$cogs,'gross_profit'=>$gross,'operating_expenses'=>$expenses,'inventory_writeoffs'=>$writeoffs,'inventory_adjustment_gains'=>$adjustmentGains,'net_profit'=>round($gross-$expenses-$writeoffs+$adjustmentGains,2)]);}


 public function balanceSheet(Request $r)
 {
  $asOf=$r->date('as_of')??today();
  $balances=DB::table('journal_entry_lines as l')->join('journal_entries as j','j.id','=','l.journal_entry_id')
   ->where('j.branch_id',BranchContext::id())->where('j.status','posted')->whereDate('j.entry_date','<=',$asOf->toDateString())
   ->groupBy('l.account_id')->selectRaw('l.account_id,SUM(l.debit) debit,SUM(l.credit) credit');
  $rows=DB::table('accounting_accounts as a')->leftJoinSub($balances,'b',fn($join)=>$join->on('b.account_id','=','a.id'))
   ->whereIn('a.type',['asset','liability','equity'])->orderBy('a.code')
   ->get(['a.id','a.code','a.name','a.type',DB::raw('COALESCE(b.debit,0) as debit'),DB::raw('COALESCE(b.credit,0) as credit')])
   ->map(function($row){$row->balance=$row->type==='asset'?(float)$row->debit-(float)$row->credit:(float)$row->credit-(float)$row->debit;return $row;});
  $pl=DB::table('journal_entry_lines as l')->join('journal_entries as j','j.id','=','l.journal_entry_id')->join('accounting_accounts as a','a.id','=','l.account_id')
   ->where('j.branch_id',BranchContext::id())->where('j.status','posted')->whereDate('j.entry_date','<=',$asOf->toDateString())
   ->whereIn('a.type',['income','expense'])
   ->selectRaw("COALESCE(SUM(CASE WHEN a.type='income' THEN l.credit-l.debit ELSE 0 END),0) as income, COALESCE(SUM(CASE WHEN a.type='expense' THEN l.debit-l.credit ELSE 0 END),0) as expenses")
   ->first();
  $currentEarnings=round((float)$pl->income-(float)$pl->expenses,2);
  $rows->push((object)['id'=>'current-earnings','code'=>'RE','name'=>'Current earnings','type'=>'equity','debit'=>0,'credit'=>$currentEarnings,'balance'=>$currentEarnings]);
  return response()->json(['as_of'=>$asOf->toDateString(),'data'=>$rows,'assets'=>(float)$rows->where('type','asset')->sum('balance'),'liabilities'=>(float)$rows->where('type','liability')->sum('balance'),'equity'=>(float)$rows->where('type','equity')->sum('balance')]);
 }

 public function cashFlow(Request $r){$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$d['from']??today()->startOfMonth()->toDateString();$to=$d['to']??today()->toDateString();$branch=BranchContext::id();$cashSales=(float)Sale::where('branch_id',$branch)->where('payment_method','cash')->whereBetween('sale_date',[$from,$to])->sum('initial_paid');$nonCashSales=(float)Sale::where('branch_id',$branch)->whereIn('payment_method',['card','online'])->whereBetween('sale_date',[$from,$to])->sum('initial_paid');$customerReceipts=(float)\App\Models\Payment::where('branch_id',$branch)->where('party_type','customer')->whereIn('method',['cash','card','online'])->whereBetween('payment_date',[$from,$to])->sum('amount');$supplierPayments=(float)\App\Models\Payment::where('branch_id',$branch)->where('party_type','supplier')->whereIn('method',['cash','bank','cheque','card','online'])->whereBetween('payment_date',[$from,$to])->sum('amount');$cashRefunds=(float)SaleReturn::where('branch_id',$branch)->whereIn('refund_method',['cash','card','online'])->whereBetween('return_date',[$from,$to])->sum('refund_amount');$supplierCashBack=(float)\App\Models\PurchaseReturn::where('branch_id',$branch)->where('refund_type','cash')->whereBetween('return_date',[$from,$to])->sum('total');$cashExpenses=(float)Expense::where('branch_id',$branch)->whereIn('payment_method',['cash','card','online'])->where('status','approved')->whereBetween('expense_date',[$from,$to])->sum('amount');$opening=(float)\App\Models\CashierSession::where('branch_id',$branch)->where('user_id',auth()->id())->whereDate('opened_at','<=',$from)->where(function($q)use($from){$q->whereNull('closed_at')->orWhereDate('closed_at','>=',$from);})->sum('opening_cash');return response()->json(['from'=>$from,'to'=>$to,'cash_sales'=>$cashSales,'non_cash_sales'=>$nonCashSales,'customer_receipts'=>$customerReceipts,'supplier_payments'=>$supplierPayments,'cash_refunds'=>$cashRefunds,'supplier_cash_back'=>$supplierCashBack,'cash_expenses'=>$cashExpenses,'net_cash_movement'=>round($cashSales+$nonCashSales+$customerReceipts+$supplierCashBack-$supplierPayments-$cashRefunds-$cashExpenses,2),'opening_cash_reference'=>$opening]);}
 public function trialBalance(Request $r){$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$d['from']??today()->startOfYear()->toDateString();$to=$d['to']??today()->toDateString();$rows=AccountingAccount::withSum(['journalLines as debit_total'=>fn($q)=>$q->whereHas('journal',fn($j)=>$j->where('branch_id',BranchContext::id())->where('status','posted')->whereBetween('entry_date',[$from,$to]))],'debit')->withSum(['journalLines as credit_total'=>fn($q)=>$q->whereHas('journal',fn($j)=>$j->where('branch_id',BranchContext::id())->where('status','posted')->whereBetween('entry_date',[$from,$to]))],'credit')->get();return response()->json(['from'=>$from,'to'=>$to,'data'=>$rows]);}
}
